-- ============================================================
-- 003 — Drill seed, part 05 of 07  (40 drills)
--
-- Paste into the Supabase SQL editor and run. Parts are independent and
-- idempotent: re-running one updates those rows rather than duplicating them.
--
-- Requires scripts/002_drill_content.sql to have been applied first.
-- ============================================================

INSERT INTO public.drills (
  slug, name, category, subcategory, type, level, duration_min, player_count, group_size, description, objective, setup, instructions, coaching_cues, common_errors, variations, tags, diagram_type, diagram_data
) VALUES
  ('MP-006', 'The Serve Game: First Serve Percentage Under Score', 'Matchplay', 'Pressure Scenarios', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Train first serve percentage under real match score pressure. Most players hit their first serve percentage drops significantly in matches compared to practice because of score pressure. This drill attaches score consequences to every serve — double faults cost bonus points, first serves in earn bonus points — creating the mental environment where serve quality actually matters.', 'Train first serve percentage under real match score pressure. Most players hit their first serve percentage drops significantly in matches compared to practice because of score pressure. This drill attaches score consequences to every serve — double faults cost bonus points, first serves in earn bonus points — creating the mental environment where serve quality actually matters.', 'Play a practice game from 0-0. The serving player earns bonus points for first serves in and loses bonus points for double faults. Normal points are also counted. This creates a two-dimensional scoring system.', ARRAY['Play a normal game from 0-0.','First serve in: +1 bonus point for the server (in addition to winning or losing the normal point).','Double fault: -2 bonus points for the server.','Second serve that is returned and won by the returner: -1 bonus point.','After the game, calculate bonus points alongside the game score. Track both over 10 games.']::text[], ARRAY['The bonus system forces attention to the serve without changing how you play the point.','A double fault costs 2 bonus points — it is the single most expensive error in this format.','First serve percentage below 50%: you are likely trying to serve too hard. Back off 10%.','Track where double faults happen: deuce or ad court? Pressure score or neutral score?','The serve should feel the same at 30-40 as it does at 40-0 — if it doesn''t, this drill reveals why.']::text[], ARRAY['Serving more conservatively just for the bonus points — defeats the training purpose.','Only tracking bonus points, not the actual game score — both matter.','Not connecting serve patterns to specific scores — data collection without analysis.']::text[], ARRAY['Ace bonus: +3 bonus points for an ace — rewards aggressive serving.','Second serve only: play entire games with only second serves — extreme pressure.','First serve win rate only: only track whether first serves in result in won points — true effectiveness metric.']::text[], ARRAY['matchplay','serve','percentage','intermediate','pressure','data']::text[], 'json', '{"p1":{"x":200,"y":860},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":160,"y1":855,"x2":240,"y2":388}],"cones":[{"x":200,"y":375},{"x":310,"y":388}]}'::jsonb),
  ('MP-007', 'Neutral, Attack, Defend: Three-State Rally', 'Matchplay', 'Tactical Awareness', 'matchplay', 'advanced', 15, 2, 'pairs', 'Develop tactical awareness of the three rally states — neutral, offensive, and defensive — and the ability to transition between them deliberately. Elite players always know which state they are in: neutral (both players even), offensive (they have an advantage), or defensive (opponent has the advantage). This drill makes that awareness explicit by requiring players to call their state before each shot.', 'Develop tactical awareness of the three rally states — neutral, offensive, and defensive — and the ability to transition between them deliberately. Elite players always know which state they are in: neutral (both players even), offensive (they have an advantage), or defensive (opponent has the advantage). This drill makes that awareness explicit by requiring players to call their state before each shot.', 'Both players rally from the baseline. Before each shot, the hitting player calls their state: ''neutral'', ''attack'', or ''defend''. The calls must be accurate — a player who calls ''attack'' from behind the baseline is incorrect.', ARRAY['Begin a baseline rally.','Before every shot, the hitting player calls their state: ''neutral'', ''attack'', or ''defend''.','Neutral: ball is deep, both players even. Hit a safe, deep shot.','Attack: a short or weak ball. Hit aggressively, go for the winner or force.','Defend: stretched, wide, or off-balance. Get the ball back safely.','Play full points. After each point, discuss: were the state calls accurate?']::text[], ARRAY['Neutral calls from within a comfortable baseline position with a bouncy-enough ball.','Attack calls only when inside the baseline or on a ball below knee level from mid-court.','Defend calls when stretched wide, pulled deep, or under pace pressure.','The most common mistake: calling ''attack'' from a neutral position and going for too much.','The second most common mistake: calling ''neutral'' from an attack position and not taking the opportunity.']::text[], ARRAY['Calling ''attack'' without the position to back it up — leads to unforced errors.','Calling ''defend'' when neutral or even attacking — builds over-cautious habits.','Not calling at all — must commit to a state before every shot.']::text[], ARRAY['Silent version: don''t call the state — play intuitively, then review the point and retroactively assign states.','Coach observes: a third person calls whether the state call was correct or incorrect.','State restriction: Player 1 can only use attack and defend (no neutral) — forces polarized decision-making.']::text[], ARRAY['matchplay','tactical awareness','three states','advanced','decision','rally']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":840,"x2":200,"y2":100},{"x1":200,"y1":70,"x2":200,"y2":820},{"x1":200,"y1":640,"x2":95,"y2":100}],"areas":[{"x":200,"y":100,"r":35},{"x":95,"y":100,"r":28}]}'::jsonb),
  ('MP-008', 'Break Point Practice: Defender and Attacker', 'Matchplay', 'Pressure Scenarios', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Train the two sides of break point — defending a break point as the server, and converting a break point as the returner. Break points are the most decisive moments in any set, and most players perform significantly worse on break points than on other points. This drill creates concentrated repetitions of exactly this scenario, training both the serving and returning skills under maximum pressure.', 'Train the two sides of break point — defending a break point as the server, and converting a break point as the returner. Break points are the most decisive moments in any set, and most players perform significantly worse on break points than on other points. This drill creates concentrated repetitions of exactly this scenario, training both the serving and returning skills under maximum pressure.', 'Every point starts at 30-40 (break point for the returner). Player 1 serves, Player 2 returns. Play the full point out. Alternate who is the server after 10 points.', ARRAY['Start every point at 30-40.','Player 1 serves — must hold serve to ''deuce'' and defend the break point.','Player 2 returns — must win the point to ''break serve''.','Play the full point out after the serve.','Track separately: Player 1''s break point save percentage and Player 2''s break point conversion rate.','After 10 points, switch roles. Play 20 total points.']::text[], ARRAY['Server at break point: stick to your serve pattern — don''t suddenly serve defensively.','Server: serve to a specific target, not just ''in'' — intention beats desperation.','Returner at break point: focus on a deep, solid return — don''t try to return for a winner.','Returner: step in on the second serve — attack the advantage you have.','Both players: breathe before the serve, stay in the present moment.']::text[], ARRAY['Server suddenly serving to a ''safe'' location — telegraphed and predictable.','Returner getting tight and missing a return they would normally make.','Both players rushing the point — break points deserve the full serve routine.']::text[], ARRAY['Game point practice: start at 40-30 — same pressure but from the other direction.','Match point practice: announce it as match point — extreme psychological pressure.','Sequential break points: Player 1 must save 3 consecutive break points to ''win'' the round.']::text[], ARRAY['matchplay','break point','pressure','intermediate','serve','return']::text[], 'json', '{"p1":{"x":200,"y":860},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":310,"y2":385},{"x1":200,"y1":70,"x2":110,"y2":820},{"x1":110,"y1":830,"x2":295,"y2":100}],"areas":[{"x":110,"y":820,"r":28},{"x":295,"y":100,"r":28}]}'::jsonb),
  ('MP-009', 'Approach and Net: Win the Point After Approaching', 'Matchplay', 'Tactical Patterns', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Develop the complete approach-to-net pattern in a match context — recognizing the short ball, approaching decisively, and finishing at the net. Many players know how to approach in isolation but freeze or make poor decisions when the point is live. This drill forces the approach decision into a real-point context with score pressure.', 'Develop the complete approach-to-net pattern in a match context — recognizing the short ball, approaching decisively, and finishing at the net. Many players know how to approach in isolation but freeze or make poor decisions when the point is live. This drill forces the approach decision into a real-point context with score pressure.', 'Player 2 mixes normal deep balls with occasional short balls. Player 1 must approach every time a short ball (inside the service line) is fed — no staying back on a short ball is allowed.', ARRAY['Player 2 and Player 1 begin a baseline rally.','Player 2 will feed a short ball (inside the service line) at any point — Player 1 must immediately approach.','Player 1 must approach and come to the net — staying back on a short ball loses the point automatically.','Player 2 attempts to pass after the approach — Player 1 volleys or overheads.','Play 20 points. Track: how many approach points does Player 1 win? Target: 60%+.']::text[], ARRAY['Short ball recognition: the ball landing inside the service line is the trigger.','Move forward immediately — every second of delay reduces the approach quality.','Approach DTL as the default — it cuts off the cross-court passing angle.','After approaching, read the passer''s swing: open face lob, closed face drive.','If winning less than 55% of approach points: approach shot is landing too short.']::text[], ARRAY['Staying back on short balls — the drill automatically penalizes this.','Approach shot landing in the service box — gives the passer an easy setup ball.','Not getting close enough to the net after the approach — allows too many passing angles.']::text[], ARRAY['Mandatory net: Player 1 must come to the net on every single point — forces net play.','Approach direction: Player 1 may only approach cross-court — tests the CC approach vs DTL.','Two-on-one approach: two baseline players vs. one net player — extreme passing pressure.']::text[], ARRAY['matchplay','approach','net play','intermediate','tactical','short ball']::text[], 'json', '{"p1":{"x":200,"y":540},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":850,"x2":200,"y2":680},{"x1":200,"y1":680,"x2":200,"y2":540}],"shots":[{"x1":200,"y1":70,"x2":200,"y2":700},{"x1":200,"y1":678,"x2":95,"y2":100},{"x1":200,"y1":60,"x2":195,"y2":620},{"x1":196,"y1":536,"x2":305,"y2":120}],"areas":[{"x":305,"y":120,"r":25}]}'::jsonb),
  ('MP-010', 'Counterpuncher vs. Aggressor: Role Assignment', 'Matchplay', 'Tactical Development', 'matchplay', 'advanced', 20, 2, 'pairs', 'Develop tactical flexibility by assigning opposite tactical roles and playing out full points within those roles. One player is the aggressor — they must attack on every short ball, come to the net, and take risks. The other is the counterpuncher — they must redirect pace, use moonballs, and win through consistency and patience. These role assignments build tactical range beyond each player''s natural game style.', 'Develop tactical flexibility by assigning opposite tactical roles and playing out full points within those roles. One player is the aggressor — they must attack on every short ball, come to the net, and take risks. The other is the counterpuncher — they must redirect pace, use moonballs, and win through consistency and patience. These role assignments build tactical range beyond each player''s natural game style.', 'Coin flip determines who is the aggressor and who is the counterpuncher. Both players play full points within their assigned roles for 10 points, then switch roles for 10 more points.', ARRAY['Aggressor role: must attack every ball that lands at or inside the service line. Must come to the net at least once every 3 points. Any ball hit slowly or softly from a neutral position loses a bonus point.','Counterpuncher role: must use high topspin or slice to redirect. Must use at least one moonball per rally. Cannot attack — can only redirect and wait.','Play 10 points per role assignment. Switch and repeat.','Track: which role produces more won points? The data reveals the player''s natural strength.']::text[], ARRAY['Aggressor: aggression must be based on ball quality, not ego — attack short balls, not deep balls.','Counterpuncher: patience is the weapon — wait for errors, don''t chase them.','Aggressor: when coming to net, split step — aggressive play still requires correct footwork.','Counterpuncher: depth and direction are the weapons — wide and deep limits the aggressor''s angles.','Most players will find one role easier — that reveals their default tactical profile.']::text[], ARRAY['Aggressor attacking from defensive positions — poor tactical judgment.','Counterpuncher abandoning patience and attacking — breaks the role assignment.','Both players reverting to neutral style — defeats the training purpose entirely.']::text[], ARRAY['Extended roles: play a full set with the assigned roles — deeper tactical immersion.','Role confusion: switch roles every 5 points without warning — tests tactical adaptability.','Natural game analysis: play 10 points with no roles, then compare to role assignments.']::text[], ARRAY['matchplay','counterpuncher','aggressor','advanced','tactical','roles']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":840,"x2":200,"y2":110},{"x1":200,"y1":70,"x2":200,"y2":820},{"x1":200,"y1":650,"x2":95,"y2":100}],"areas":[{"x":200,"y":110,"r":40},{"x":95,"y":100,"r":28}]}'::jsonb),
  ('MP-011', 'Third Set Mental Toughness: Play When Tired', 'Matchplay', 'Mental Fitness', 'matchplay', 'advanced', 20, 2, 'pairs', 'Train competitive quality specifically when physically and mentally fatigued — the conditions of the third set of a close match. Most competitive matches are decided in the third set, and the player who maintains their game plan, serve patterns, and tactical thinking under fatigue usually wins. This drill places both players in a genuinely fatigued state before beginning competitive play.', 'Train competitive quality specifically when physically and mentally fatigued — the conditions of the third set of a close match. Most competitive matches are decided in the third set, and the player who maintains their game plan, serve patterns, and tactical thinking under fatigue usually wins. This drill places both players in a genuinely fatigued state before beginning competitive play.', 'Both players complete a 10-minute physical circuit before the drill (spider runs, lateral shuffles, and suicide runs) until they are genuinely fatigued. Immediately after, they play competitive points.', ARRAY['Phase 1 — Physical load: both players complete 3 spider runs, 3 lateral sideline-to-sideline shuffles, and 2 suicide runs without rest.','Phase 2 — Immediate competitive play: without rest, play 15 competitive points from scratch.','Both players must maintain full serve routines, between-point rituals, and tactical thinking.','Track: does serve quality degrade? Do tactical patterns simplify? Does competitive effort drop?','Debrief after the drill: what degraded first? What held up?']::text[], ARRAY['Mental reset after the physical phase: use the breathing protocol to transition into competitive mode.','Maintain the between-point routine — this is the anchor when the body is fatigued.','Notice which technical skills degrade first under fatigue — those need specific targeted training.','Keep serving to your patterns — the serve is the one shot where you have full control.','A player who can maintain their game under fatigue has a significant competitive advantage.']::text[], ARRAY['Reducing the physical load to preserve match quality — the fatigue is the training stimulus.','Abandoning serve routines when tired — exactly when they are most needed.','Not tracking what degrades — the drill has no value without honest post-drill analysis.']::text[], ARRAY['Escalating fatigue: add one extra sprint before each group of 5 points — fatigue compounds.','Third set simulation: play full games with the physical load before every service game.','Fitness first: complete the full fitness drill from FT-025 then immediately compete.']::text[], ARRAY['matchplay','mental toughness','fatigue','advanced','third set','competition']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":120,"y":60},"moves":[{"x1":200,"y1":850,"x2":200,"y2":480},{"x1":200,"y1":480,"x2":200,"y2":850}],"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":120,"y1":70,"x2":280,"y2":820}]}'::jsonb),
  ('MP-012', 'No Unforced Error Game: Zero Tolerance Points', 'Matchplay', 'Tactical Development', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Build a zero-unforced-error mentality through a game where unforced errors cost double. Most club players lose far more points from unforced errors than from opponents'' winners. Training under a zero-error penalty system forces a tactical shift: higher margin on all shots, deeper targets, more conservative attack timing, and a fundamentally more solid game style that transfers directly to match play.', 'Build a zero-unforced-error mentality through a game where unforced errors cost double. Most club players lose far more points from unforced errors than from opponents'' winners. Training under a zero-error penalty system forces a tactical shift: higher margin on all shots, deeper targets, more conservative attack timing, and a fundamentally more solid game style that transfers directly to match play.', 'Play normal points but with modified scoring: a normal error (close attempt) counts as 1 point lost. An unforced error (easy ball missed) counts as 2 points lost. Both players must agree before the match on what constitutes an unforced error.', ARRAY['Define unforced error: a ball missed when in a comfortable position with time to set up.','Play normal points.','Normal point won/lost: +1/-1. Unforced error: -2 (the opponent gets 2 points instead of 1).','Players call their own unforced errors — honest self-assessment is required.','Play first to 15 bonus points. Track unforced error count throughout.']::text[], ARRAY['Aim 3 feet inside the lines — the penalty forces larger margins.','Attack only from positions of strength — a slightly short ball is not the same as a sitting ball.','When in doubt, add spin — topspin reduces unforced errors by creating a safety arc.','Track which shots produce your unforced errors — forehand, backhand, or volley?','Calling your own unforced errors honestly is the most valuable part of this drill.']::text[], ARRAY['Calling all errors ''forced'' — dishonest self-assessment defeats the purpose.','Playing too defensively — the goal is fewer errors, not fewer shots.','Not tracking unforced error patterns — the data is more valuable than the game result.']::text[], ARRAY['Winner bonus: +2 for outright winners — balances the unforced error penalty.','Unforced error tracking only: don''t change scoring, just count unforced errors — baseline data.','Double penalty game: unforced error = -3 — extreme version for players who are cavalier.']::text[], ARRAY['matchplay','unforced error','consistency','intermediate','mental','margin']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":840,"x2":190,"y2":110},{"x1":200,"y1":70,"x2":210,"y2":820}],"areas":[{"x":190,"y":110,"r":40},{"x":210,"y":820,"r":40}]}'::jsonb),
  ('MP-013', 'Serve Pattern Library: Five Patterns Per Court', 'Matchplay', 'Tactical Patterns', 'matchplay', 'intermediate', 20, 2, 'pairs', 'Build a personal serve pattern library — 5 specific serve-plus-one patterns from the deuce court and 5 from the ad court — and execute them under real match conditions. Most players serve reactively, choosing serve location after the serve rather than before. Building a deliberate pattern library forces tactical intentionality on every serve and produces significantly better serve game performance.', 'Build a personal serve pattern library — 5 specific serve-plus-one patterns from the deuce court and 5 from the ad court — and execute them under real match conditions. Most players serve reactively, choosing serve location after the serve rather than before. Building a deliberate pattern library forces tactical intentionality on every serve and produces significantly better serve game performance.', 'Player 1 writes down (on a sheet or in their mind) 5 patterns from each court. Example deuce patterns: T flat + inside-out FH, wide slice + CC FH, T kick + CC BH. Player 1 must use only their declared patterns during the drill.', ARRAY['Player 1 selects 5 serve patterns from the deuce court (serve location + plus-one shot).','Player 1 serves from the deuce court, using only their 5 declared patterns.','Player 1 calls the pattern before each serve (quietly — they don''t tell Player 2).','After 10 points, switch to ad court patterns. Play 10 more points.','Track: which patterns produce the most points won? Which produce the most errors?']::text[], ARRAY['Each pattern must be a complete serve-plus-one sequence — not just a serve location.','Vary patterns across the 10 points — don''t use the same pattern 5 times in a row.','The plus-one must be executed even if the return comes back differently than expected.','Some patterns will outperform others against specific opponents — note this.','After the drill: rank your 5 patterns by effectiveness. The top 2 are your ''go-to'' patterns.']::text[], ARRAY['Declaring only serve locations without plus-one shots — incomplete pattern planning.','Using the same 1-2 patterns throughout — doesn''t build the full library.','Abandoning the pattern when the serve is not ideal — the discipline is part of the training.']::text[], ARRAY['Pattern tournament: play 5 points with each pattern, score which wins most — find the best pattern.','Partner reads: Player 2 tries to guess the pattern from the serve — tests disguise quality.','Library expansion: build a library that includes second serve patterns as well.']::text[], ARRAY['matchplay','serve pattern','library','intermediate','tactical','planning']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":160,"y":60},"shots":[{"x1":240,"y1":850,"x2":200,"y2":375},{"x1":240,"y1":850,"x2":315,"y2":388},{"x1":240,"y1":850,"x2":148,"y2":382}],"cones":[{"x":200,"y":375},{"x":315,"y":388},{"x":148,"y":382}]}'::jsonb),
  ('MP-014', 'Winner or Error Analysis: Tracking Point-Ending Shots', 'Matchplay', 'Match Analysis', 'matchplay', 'intermediate', 20, 2, 'pairs', 'Develop tactical self-awareness through real-time tracking of how each point ends: winner, forced error, or unforced error. The ratio of winners to unforced errors is the most important tactical metric in tennis. Most players believe they win through winners but actually win through opponents'' unforced errors. This drill creates immediate clarity about how points are actually won and lost.', 'Develop tactical self-awareness through real-time tracking of how each point ends: winner, forced error, or unforced error. The ratio of winners to unforced errors is the most important tactical metric in tennis. Most players believe they win through winners but actually win through opponents'' unforced errors. This drill creates immediate clarity about how points are actually won and lost.', 'A third person observes (or Player 2 records on the next point) every point result: W (winner for either player), FE (forced error), UE (unforced error), and who committed it. Both players play normally.', ARRAY['Play 20 competitive points from the serve.','Observer (or Player 2 on subsequent points) records: who won, and how — W, FE, or UE.','After 20 points, calculate: winner-to-unforced-error ratio for each player.','Discuss: what patterns emerge? Who wins through errors? Who wins through winners?','Set a specific goal for the next 20 points based on the data.']::text[], ARRAY['Winner: ball lands in the court and the opponent cannot touch it.','Forced error: opponent makes a mistake but only because of a quality shot that pushed them out of position.','Unforced error: ball missed when in a comfortable position with time to set up properly.','Elite players have a winner-to-UE ratio of 1:1 or better — most club players have 1:3 or worse.','The data is the coaching — the numbers tell you exactly what to work on.']::text[], ARRAY['Not recording honestly — calling forced errors unforced or vice versa.','Not using the data — playing 20 more points without adjusting based on what the data shows.','Only tracking one player — both players'' data is equally valuable.']::text[], ARRAY['Rally length tracking: add rally length (number of shots) to the recording.','Shot type tracking: record which shot type ended the point — forehand, backhand, serve, volley.','Weekly comparison: run this drill monthly and compare UE/winner ratios over time.']::text[], ARRAY['matchplay','analysis','winner','unforced error','intermediate','data']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":840,"x2":95,"y2":100},{"x1":200,"y1":70,"x2":295,"y2":820}],"areas":[{"x":95,"y":100,"r":28},{"x":295,"y":820,"r":28}]}'::jsonb),
  ('MP-015', 'Playing to a Weakness: Targeting the Opponent', 'Matchplay', 'Tactical Development', 'matchplay', 'advanced', 20, 2, 'pairs', 'Develop the tactical habit of identifying and consistently targeting an opponent''s weakness. One of the most effective match strategies is identifying the weaker wing, the weaker serve return, or the weaker movement direction and systematically directing play there. This requires tactical discipline — resisting the natural instinct to go to your own strength and instead going to the opponent''s weakness.', 'Develop the tactical habit of identifying and consistently targeting an opponent''s weakness. One of the most effective match strategies is identifying the weaker wing, the weaker serve return, or the weaker movement direction and systematically directing play there. This requires tactical discipline — resisting the natural instinct to go to your own strength and instead going to the opponent''s weakness.', 'Before the drill, both players declare their partner''s weakness (e.g., ''your backhand'' or ''your movement to the left''). Player 1 must direct at least 70% of shots to the declared weakness throughout the drill.', ARRAY['Both players identify and declare each other''s weakness before playing.','Player 1 must direct 70% of their shots to Player 2''s declared weakness throughout the drill.','Player 2 plays freely — they know where the ball is coming, which replicates a prepared opponent.','Play 15 points. Track: what percentage of Player 1''s shots actually went to the weakness?','Switch roles. Player 2 now targets Player 1''s weakness.']::text[], ARRAY['Targeting a weakness requires changing your own comfortable patterns — that''s the discipline challenge.','Even when Player 2 knows where it''s coming, the weakness should still produce more errors.','The weakness might not be technical — it could be movement, position, or confidence.','Don''t obsess so much on the weakness that you miss an obvious winning shot elsewhere.','After the drill: did targeting the weakness work? If not, why not? That answer is valuable.']::text[], ARRAY['Not going to the weakness consistently — defaulting to comfortable patterns.','Targeting the weakness even from impossible positions — must still make tactical sense.','Identifying the wrong weakness — the opponent may appear weak in one area but be well-prepared there.']::text[], ARRAY['Unknown weakness: Player 1 must identify the weakness through play (no pre-declaration) and target it.','Dynamic weakness: Player 2''s weakness changes mid-drill — requires Player 1 to re-identify.','Weakness overload: 90% of shots to the weakness — extreme targeting discipline.']::text[], ARRAY['matchplay','weakness targeting','tactical','advanced','strategy','opponent analysis']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":120,"y":60},"shots":[{"x1":120,"y1":840,"x2":110,"y2":100},{"x1":120,"y1":60,"x2":295,"y2":820},{"x1":295,"y1":830,"x2":110,"y2":100}],"areas":[{"x":110,"y":100,"r":35}]}'::jsonb),
  ('MP-016', 'Tiebreak from 6-6: Match Pressure Simulation', 'Matchplay', 'Pressure Scenarios', 'matchplay', 'advanced', 15, 2, 'pairs', 'Train the full match tiebreak — the highest-pressure situation in tennis. A tiebreak at 6-6 in the third set represents the ultimate test of all tennis skills: technique, tactics, fitness, and mental composure. This drill creates that scenario repeatedly, building familiarity with the format, the pressure, and the mental demands of competing at maximum stakes.', 'Train the full match tiebreak — the highest-pressure situation in tennis. A tiebreak at 6-6 in the third set represents the ultimate test of all tennis skills: technique, tactics, fitness, and mental composure. This drill creates that scenario repeatedly, building familiarity with the format, the pressure, and the mental demands of competing at maximum stakes.', 'Both players begin a standard tiebreak from 0-0. Normal tiebreak scoring: first to 7 points, win by 2. Serve alternates every 2 points, starting serve is determined by coin flip. Both players play as if the match depends on this tiebreak — it does.', ARRAY['Announce ''tiebreak, 6-6 in the third set'' before starting — creates the mental context.','Player 1 serves the first 1 point, then serve alternates every 2 points.','Play to 7 points, win by 2.','After the tiebreak, immediately play another — first player to win 3 tiebreaks wins the session.','Track every serve placement, return direction, and point-ending shot.']::text[], ARRAY['Tiebreaks are won through consistency and serve patterns — not through risky shots.','Use your strongest serve pattern — this is not the time for experimentation.','Return deep and cross-court on the first return — neutralize the serve advantage.','At 6-6 in the tiebreak: don''t change anything. Trust what got you here.','Post-tiebreak review: which serve patterns won points? Which returns caused errors?']::text[], ARRAY['Suddenly going for more on shots in the tiebreak — risk should decrease, not increase.','Forgetting the serve rotation — serves must alternate correctly.','Not using the between-point time for breathing and resetting.']::text[], ARRAY['Start the tiebreak at 5-5 — fewer points but more concentrated pressure.','Tiebreak series: play 7 tiebreaks in a row — builds tiebreak rhythm and pattern familiarity.','Super tiebreak: first to 10 (win by 2) — used as the third set in many pro formats.']::text[], ARRAY['matchplay','tiebreak','advanced','pressure','match point','mental']::text[], 'json', '{"p1":{"x":200,"y":860},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":200,"y1":70,"x2":280,"y2":820},{"x1":280,"y1":830,"x2":100,"y2":100}],"areas":[{"x":280,"y":820,"r":28},{"x":100,"y":100,"r":28}]}'::jsonb),
  ('MP-017', 'No Backhand Game: Tactical Constraint Practice', 'Matchplay', 'Tactical Development', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Develop tactical creativity and forced pattern exploration through a constraint game where the backhand is not allowed. When the backhand is removed, players must use inside-out forehands, run around backhands, and create entirely different movement patterns to cover the court. This constraint forces tactics that are rarely used naturally and builds the inside-out forehand as a real weapon.', 'Develop tactical creativity and forced pattern exploration through a constraint game where the backhand is not allowed. When the backhand is removed, players must use inside-out forehands, run around backhands, and create entirely different movement patterns to cover the court. This constraint forces tactics that are rarely used naturally and builds the inside-out forehand as a real weapon.', 'Both players play full points but neither player may hit a backhand. Any backhand shot hit into the court costs the hitter 1 bonus point. Players must run around every backhand and use a forehand, or let the ball go out. Both players must follow the rule.', ARRAY['Both players are prohibited from hitting backhand shots.','Any backhand hit in the court: the hitter loses -1 bonus point.','Players must run around backhands to hit inside-out or inside-in forehands, or let the ball go out.','Play 20 points under this constraint.','Track: how many inside-out forehands does each player hit? Does the pattern change the tactics?']::text[], ARRAY['The inside-out forehand becomes mandatory — use this drill to groove the run-around.','Court positioning changes: stand slightly further left (for right-handers) to cover the backhand.','The constraint reveals how often backhands are used — most players use them far more than they realize.','Serve from the deuce court wide — pulls the ball to your forehand on the plus-one.','Don''t race around every backhand — let some balls go out rather than hitting a bad inside-out.']::text[], ARRAY['Panicking and hitting backhands — must accept losing some points to maintain the constraint.','Inside-out forehands with poor technique — better to let the ball go out than to hit a bad shot.','Not adjusting the serve to accommodate the constraint — serve wide to set up the forehand.']::text[], ARRAY['No forehand game: both players can only use backhand — forces the backhand as the dominant shot.','One-wing game: Player 1 has no backhand, Player 2 plays normally — asymmetric challenge.','Alternating wings: alternate no-backhand and no-forehand games — develops both wings.']::text[], ARRAY['matchplay','constraint','forehand','intermediate','inside-out','tactical']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":850,"x2":120,"y2":850}],"shots":[{"x1":200,"y1":70,"x2":155,"y2":840},{"x1":120,"y1":840,"x2":95,"y2":100},{"x1":120,"y1":840,"x2":295,"y2":100}],"areas":[{"x":95,"y":100,"r":25},{"x":295,"y":100,"r":25}]}'::jsonb),
  ('MP-018', 'Playing from Behind: 0-4 Comeback Drill', 'Matchplay', 'Mental Fitness', 'matchplay', 'advanced', 20, 2, 'pairs', 'Build the mentality and tactical skills needed to come back from a deficit — one of the most important competitive skills in tennis. Starting from 0-4 down in a set forces players to compete under adversity, find ways to change momentum, and stay mentally present rather than collapsing. The ability to fight back from a deficit has decided countless major matches.', 'Build the mentality and tactical skills needed to come back from a deficit — one of the most important competitive skills in tennis. Starting from 0-4 down in a set forces players to compete under adversity, find ways to change momentum, and stay mentally present rather than collapsing. The ability to fight back from a deficit has decided countless major matches.', 'Player 1 starts at 0-4 in a set. Player 2 starts at 4-0. Both players play out the set from this score. Player 1 must try to come back and win the set. No gifts — Player 2 plays competitively to hold the lead.', ARRAY['Begin the set at 0-4 (Player 1) vs 4-0 (Player 2).','Player 1 serves first from the 0-4 position.','Play full games with normal scoring from this starting position.','The set ends when one player reaches 6 games (win by 2) or a tiebreak at 6-6.','Track: does Player 1 successfully come back? What tactical changes (if any) helped the comeback?']::text[], ARRAY['0-4 is not 0-0 — acknowledge the deficit without catastrophizing it.','Change one thing tactically: new serve location, different return position, or a new pattern.','Winning the next game is the only goal — not winning the set. One game at a time.','Player 2 should not give anything away — an honest test requires genuine competition.','The comeback mindset: ''one point at a time'' is not a cliche — it is literally the only strategy.']::text[], ARRAY['Player 1 giving up mentally at 0-4 — the deficit is only 4 games, not the match.','Player 1 trying to change too many things at once — one tactical change, not five.','Player 2 easing up — the deficit only has training value if it is earned against real competition.']::text[], ARRAY['0-5 comeback: even more pressure — two games from losing the set.','Match comeback: start at 0-6, 0-4 in the second set — full match comeback simulation.','Comeback statistics: track over 10 sessions, how often does Player 1 come back from 0-4?']::text[], ARRAY['matchplay','comeback','mental toughness','advanced','deficit','resilience']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":200,"y1":70,"x2":110,"y2":820},{"x1":110,"y1":830,"x2":295,"y2":100}],"areas":[{"x":200,"y":850,"r":20}]}'::jsonb),
  ('MP-019', 'Rally Length Zones: Short, Medium, Long Point Training', 'Matchplay', 'Tactical Development', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Develop tactical competence across different rally length zones. Most players are comfortable in one rally length zone — either short points (attackers) or long points (baseliners) — but struggle in others. This drill trains all three zones explicitly and reveals the tactical and physical profile of each player.', 'Develop tactical competence across different rally length zones. Most players are comfortable in one rally length zone — either short points (attackers) or long points (baseliners) — but struggle in others. This drill trains all three zones explicitly and reveals the tactical and physical profile of each player.', 'Play three rounds of 10 points each. Round 1: short-point training (must win or lose within 4 shots). Round 2: medium-point training (point must last 5-8 shots). Round 3: long-point training (point must last 9+ shots). Any point ending outside the target zone is replayed.', ARRAY['Round 1 (10 points): short rally — if the point is still going after 4 shots, the current shooter must attack aggressively.','Round 2 (10 points): medium rally — if the point ends before 5 shots, the point is replayed.','Round 3 (10 points): long rally — both players must rally for 9+ shots before a winner or error.','Track win rate in each zone. The zone with the lowest win rate is the tactical weakness.','Discuss: what tactics work in each zone? What fails?']::text[], ARRAY['Short points favor aggressive servers and strong returners — take risks early.','Medium points require controlled aggression: build the first 3 shots, then attack on the 4th or 5th.','Long points favor consistent baseliners — depth, spin, and patience are the weapons.','Most competitive matches have a mix of all three — a balanced game wins more situations.','Your win rate in each zone is your tactical profile — know it and train the weak zone.']::text[], ARRAY['Not adjusting tactics between rounds — each zone requires a different approach.','Ending the long rally with a risky shot just because it''s been many shots.','Forcing a short point in the medium round by hitting too hard.']::text[], ARRAY['Zone preference: each player must win in their weakest zone — targeted improvement.','Zone matching: two aggressors play the long-point round — tests adaptability.','Zone tracking over a match: count rally lengths in a real match — identify your natural zone.']::text[], ARRAY['matchplay','rally length','tactical','intermediate','zones','profiling']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":840,"x2":200,"y2":100},{"x1":200,"y1":70,"x2":200,"y2":820},{"x1":200,"y1":820,"x2":95,"y2":100}],"areas":[{"x":200,"y":460,"r":50}]}'::jsonb),
  ('MP-020', 'One Set Match with Structured Changeover Review', 'Matchplay', 'Match Assessment', 'matchplay', 'intermediate', 30, 2, 'pairs', 'Play a complete practice set with structured tactical reviews at every changeover — building the habit of tactical adjustment within a match. Most players change nothing between games, even when a pattern is clearly not working. The structured changeover review forces reflection, adjustments, and plan re-execution — the skills that separate tactical players from reactive ones.', 'Play a complete practice set with structured tactical reviews at every changeover — building the habit of tactical adjustment within a match. Most players change nothing between games, even when a pattern is clearly not working. The structured changeover review forces reflection, adjustments, and plan re-execution — the skills that separate tactical players from reactive ones.', 'Play a full set (first to 6, win by 2). At every changeover (after every 2 games), both players spend 60 seconds on a structured 3-question review before continuing.', ARRAY['Play 2 games. At the changeover (90-second maximum), both players answer 3 questions: What is working? What is not working? What is one thing I will change?','Write the answers down if possible, or state them aloud.','Play the next 2 games using the declared change.','Repeat at every changeover throughout the set.','After the set: review all changeover notes — did the changes help? What pattern emerged?']::text[], ARRAY['Answer each question specifically: not ''serve better'' — ''serve wide on deuce court more''.','One change at a time — multiple simultaneous changes cause confusion, not improvement.','The change must be tactical, not technical — you cannot fix your forehand in a changeover.','After implementing a change, give it 4 points to evaluate — don''t abandon it after one miss.','The changeover review habit is a competitive skill — practice it so it becomes automatic in real matches.']::text[], ARRAY['Generic answers: ''play better'' is not a tactical answer.','Too many changes: one change per changeover maximum.','Abandoning the review when leading — tactical review is most important when winning.']::text[], ARRAY['Pre-written strategy: both players write 3 pre-match tactics, track if they use them.','Partner review: both players share their changeover answers with each other — mutual feedback.','Post-match full review: review all changeover notes after the full set — identify patterns.']::text[], ARRAY['matchplay','set','changeover','intermediate','tactical review','adjustment']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":200,"y1":70,"x2":280,"y2":820},{"x1":280,"y1":830,"x2":100,"y2":100},{"x1":100,"y1":820,"x2":295,"y2":100}],"areas":[{"x":280,"y":820,"r":28},{"x":100,"y":100,"r":28}]}'::jsonb),
  ('MP-021', 'Second Serve Game: When First Serve Goes Out', 'Matchplay', 'Pressure Scenarios', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Train the tactical response to missing the first serve — how to serve, rally, and manage the point from the second serve disadvantage. Most players miss the first serve and immediately shift to a conservative, defensive mindset on the second serve. This drill makes second serve situations a training focus, building both second serve quality and the competitive mindset needed to play aggressively from a second serve.', 'Train the tactical response to missing the first serve — how to serve, rally, and manage the point from the second serve disadvantage. Most players miss the first serve and immediately shift to a conservative, defensive mindset on the second serve. This drill makes second serve situations a training focus, building both second serve quality and the competitive mindset needed to play aggressively from a second serve.', 'All points in this drill begin with a second serve — no first serves allowed. The server must use their second serve motion (spin serve) for every delivery. Points are scored normally.', ARRAY['Player 1 serves with only second serve motion (spin serve) — no flat first serves.','Player 2 returns aggressively — knowing it''s always a second serve.','Both players play out the full point from the second serve start.','Play 15 points, then switch servers.','Track: Player 1''s second serve win percentage. Target: 45%+ (even on second serves).']::text[], ARRAY['Second serves must have quality: deep, with spin, and to a specific location.','The server should still have a plus-one plan — even on second serves.','Use the kick second serve to the backhand as the primary weapon.','After missing the first serve, the mental reset must be complete before the second serve routine.','A player who wins 45%+ on second serves has a dangerous second serve — strive for this.']::text[], ARRAY['Serving second serves to safe, predictable locations — easily attackable.','No plus-one plan on second serve — playing reactively from the start.','Short second serves that sit up — give the returner an easy attack opportunity.']::text[], ARRAY['Second serve only set: play a full set with only second serves — deep performance test.','Mixed: alternate first and second serve starts — compares win rates in each scenario.','Second serve attack: server must attack the plus-one on every second serve point — aggressive mindset.']::text[], ARRAY['matchplay','second serve','intermediate','pressure','win rate','mindset']::text[], 'json', '{"p1":{"x":200,"y":860},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":850,"x2":240,"y2":385},{"x1":200,"y1":60,"x2":110,"y2":820}],"areas":[{"x":240,"y":385,"r":30}]}'::jsonb),
  ('MP-022', 'Handicap Match: Equalizing Competition', 'Matchplay', 'Competitive Play', 'matchplay', 'beginner', 20, 2, 'pairs', 'Create competitive balance between players of different skill levels through a handicap scoring system, enabling high-quality competitive practice for both players. One-sided practice matches have limited value for the stronger player (too easy) and can be demoralizing for the weaker player. Handicap matches maximize the competitive pressure for both players simultaneously.', 'Create competitive balance between players of different skill levels through a handicap scoring system, enabling high-quality competitive practice for both players. One-sided practice matches have limited value for the stronger player (too easy) and can be demoralizing for the weaker player. Handicap matches maximize the competitive pressure for both players simultaneously.', 'Determine the skill gap. For a 3-skill-level difference: the weaker player starts every game at 30-0 advantage. For a 1-level difference: weaker player starts every game at 15-0. This balances the competitive intensity.', ARRAY['Assess the skill gap and assign the appropriate starting score advantage to the weaker player.','Both players play full points from the handicapped starting score.','The stronger player must win from behind more often — creates challenge and pressure.','The weaker player must still win the points — the handicap creates opportunity, not gifts.','Play a full set with the handicap. Adjust the handicap if the result is still too one-sided.']::text[], ARRAY['The handicap should produce a closely contested match — if one player wins easily, the handicap is wrong.','Stronger player: treat every point as competitive — don''t relax because of the handicap.','Weaker player: the handicap creates opportunity. Earn the points — don''t expect gifts.','Both players: the competitive intensity from a close match is the training stimulus.','Adjust the handicap after each match until the games are genuinely competitive.']::text[], ARRAY['Handicap too large — weaker player wins without working hard.','Handicap too small — still one-sided, weaker player gets frustrated.','Strong player not competing fully — reduces training value for both.']::text[], ARRAY['Game handicap: weaker player starts the set at 3-0 up.','Shot handicap: stronger player can only use one side (forehand or backhand) — technical limitation.','Double bounces: weaker player may let the ball bounce twice before hitting — time pressure equalizer.']::text[], ARRAY['matchplay','handicap','competitive','beginner','equalization','match practice']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":200,"y1":70,"x2":280,"y2":820}],"areas":[{"x":200,"y":850,"r":30},{"x":200,"y":60,"r":30}]}'::jsonb),
  ('MP-023', 'Doubles Formation: I-Formation Serve', 'Matchplay', 'Doubles Tactics', 'matchplay', 'advanced', 12, 2, 'pairs', 'Develop the doubles I-formation — one of the most effective and underused tactical formations in doubles. The I-formation places the net player directly in the center at the net, and the server signals left or right to indicate which side they will move after the serve. This formation creates confusion for the returner (they cannot read where the net player will move) and often produces weak returns or outright winners.', 'Develop the doubles I-formation — one of the most effective and underused tactical formations in doubles. The I-formation places the net player directly in the center at the net, and the server signals left or right to indicate which side they will move after the serve. This formation creates confusion for the returner (they cannot read where the net player will move) and often produces weak returns or outright winners.', 'Two players act as a doubles team. Player 1 serves. Player 2 (net player) crouches at the center strap of the net. Player 1 signals (left or right) with fingers behind the back — Player 2 moves that direction when the serve is hit. A third player (or a cone) represents the opposing returner.', ARRAY['Player 2 crouches at the center strap, facing the net.','Player 1 signals the direction before serving — Player 2 must remember the signal.','Player 1 serves. The moment the ball leaves the racket, Player 2 moves to the signaled side.','If the return comes back, Player 1 is covering the other side.','Practice 15 I-formation serves from each court. Track: how many returns are intercepted by Player 2?']::text[], ARRAY['Player 2: stay crouched until the serve is hit — moving early gives away the formation.','Player 1: serve as fast and accurate as possible — the I-formation loses value with a weak serve.','Player 2: move decisively and early after the signal — no hesitation.','The I-formation is most effective when used occasionally — overuse allows opponents to predict.','Player 1: cover the side Player 2 vacates — communication is essential.']::text[], ARRAY['Player 2 moving early — the returner reads the movement and aims the other way.','Player 1 forgetting to cover the vacated side.','Overusing the I-formation — becomes predictable after 3-4 uses per set.']::text[], ARRAY['Australian formation: Player 2 starts on the same side as the server — different positioning.','Signal variation: use multiple signals (not just left/right) to add complexity.','Real match I-formation: use it in a practice set — track how many times it produces a weak return.']::text[], ARRAY['matchplay','doubles','I-formation','advanced','tactics','serve']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":200,"y":490},"moves":[{"x1":200,"y1":490,"x2":130,"y2":490}],"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":60,"x2":200,"y2":840}],"areas":[{"x":200,"y":490,"r":20}]}'::jsonb),
  ('MP-024', 'Emotional Reset Protocol: Between-Point Routine', 'Matchplay', 'Mental Fitness', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Develop a structured emotional reset protocol that prevents the emotional spillover from bad points into subsequent points. The most common mental performance problem in competitive tennis is carrying the emotion of a bad point into the next point — creating errors that compound and produce losing streaks. A trained between-point routine prevents this by creating a psychological reset after every single point.', 'Develop a structured emotional reset protocol that prevents the emotional spillover from bad points into subsequent points. The most common mental performance problem in competitive tennis is carrying the emotion of a bad point into the next point — creating errors that compound and produce losing streaks. A trained between-point routine prevents this by creating a psychological reset after every single point.', 'Both players play full points. After every single point — winner or loser — Player 1 must perform a specific 4-step between-point routine before the next serve. Player 2 observes and calls if Player 1 skips any step.', ARRAY['Define Player 1''s 4-step routine: Step 1: turn away from the net (face back fence). Step 2: breathe (exhale fully). Step 3: positive self-talk or trigger word. Step 4: decision (serve target or return position).','After every point, Player 1 must complete all 4 steps before serving or returning.','Player 2 calls ''incomplete'' if Player 1 skips a step.','Play 20 points. Track: how many complete routines were executed without being called incomplete?','Target: 18 of 20 complete routines.']::text[], ARRAY['Step 1 (turn away): physically separates the past point from the present.','Step 2 (breathe): exhaling releases physical tension built up during the point.','Step 3 (trigger word): one word that centers your focus — ''ready'', ''present'', ''next''.','Step 4 (decision): the serve target or return position commits the mind to the next point.','The routine should take 8-12 seconds — not rushed, not slow.']::text[], ARRAY['Skipping the routine after good points — it is equally important after winning as losing.','Routine too long — players cannot sustain a 30-second routine under pressure.','Trigger words without meaning — the trigger must have a genuine centering effect.']::text[], ARRAY['Personalized routine: Player 1 develops their own 4 steps based on what helps them specifically.','Tracked over a real match: mark on a scorecard whether the routine was completed after each point.','Speed routine: the same 4 steps in 5 seconds — for players who naturally take too long between points.']::text[], ARRAY['matchplay','mental','between points','intermediate','routine','emotional reset']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":850,"x2":200,"y2":870}],"areas":[{"x":200,"y":850,"r":20}]}'::jsonb),
  ('MP-025', 'Pattern Recognition: What Does This Opponent Do?', 'Matchplay', 'Tactical Development', 'matchplay', 'advanced', 20, 2, 'pairs', 'Develop real-time opponent pattern recognition — identifying what an opponent tends to do in specific situations and using that information to anticipate and exploit. Every player has patterns: a serve they use at break point, a rally shot they default to under pressure, or a movement they favor. The player who identifies and acts on patterns first gains a significant competitive advantage.', 'Develop real-time opponent pattern recognition — identifying what an opponent tends to do in specific situations and using that information to anticipate and exploit. Every player has patterns: a serve they use at break point, a rally shot they default to under pressure, or a movement they favor. The player who identifies and acts on patterns first gains a significant competitive advantage.', 'Play 10 points with Player 1 deliberately creating opportunities to recognize Player 2''s patterns. After 10 points, Player 1 identifies 2-3 specific patterns they observed. Then play 10 more points using that information.', ARRAY['Phase 1 (10 points): Player 1 actively watches for patterns. After each point, Player 1 mentally notes: What did Player 2 do? Was it a pattern?','Break after 10 points: Player 1 declares 2-3 patterns observed (e.g., ''Player 2 always goes DTL when pushed wide'').','Phase 2 (10 more points): Player 1 uses the identified patterns to anticipate and position early.','Compare win rate in Phase 1 vs Phase 2. The improvement is the value of pattern recognition.','Switch roles and repeat.']::text[], ARRAY['Watch for serve patterns: same serve at deuce, same serve on break point.','Watch for pressure patterns: under pressure, most players default to cross-court.','Watch for movement patterns: does Player 2 always recover to the same spot?','Watch for toss-reveal patterns: the toss tells you where the serve is going before contact.','Act on patterns immediately — the sooner you move, the more valuable the read.']::text[], ARRAY['Identifying false patterns: one instance is not a pattern — need at least 3 repetitions.','Over-committing to patterns: if Player 2 breaks the pattern once, don''t abandon the read.','Not tracking patterns during Phase 1 — must be actively observing, not just playing.']::text[], ARRAY['Blind pattern: Player 1 doesn''t declare patterns — just uses them silently during Phase 2.','Pattern test: Player 2 deliberately creates a false pattern then breaks it — tests Player 1''s commitment.','Match pattern journal: after every match, both players write down 3 patterns they identified.']::text[], ARRAY['matchplay','pattern recognition','advanced','tactical','opponent reading','anticipation']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":200,"y1":70,"x2":295,"y2":820},{"x1":295,"y1":830,"x2":95,"y2":100}],"areas":[{"x":295,"y":820,"r":28}]}'::jsonb),
  ('MP-026', 'Lob or Pass Decision: Reading the Net Player', 'Matchplay', 'Tactical Development', 'matchplay', 'intermediate', 12, 2, 'pairs', 'Develop the real-time decision between a lob and a passing shot when a net player is present. This is one of the most tactically complex decisions in tennis and one that most players make poorly under pressure. The decision depends on the net player''s position, height, and movement, the baseliner''s court position, and the ball quality. This drill creates the specific situations that demand this decision repeatedly.', 'Develop the real-time decision between a lob and a passing shot when a net player is present. This is one of the most tactically complex decisions in tennis and one that most players make poorly under pressure. The decision depends on the net player''s position, height, and movement, the baseliner''s court position, and the ball quality. This drill creates the specific situations that demand this decision repeatedly.', 'Player 1 is at the baseline. Player 2 is at the net. Player 2 varies their net position: sometimes close to the net (inviting the lob), sometimes further back (inviting the pass). Player 1 must read the position and choose the correct option.', ARRAY['Player 2 takes up a net position — sometimes close, sometimes mid-service box.','Player 1 is fed a ball from outside the court.','Player 1 must choose: lob or pass based on Player 2''s position.','Close to net = lob. Mid-service box = pass. Both are valid against a centered position.','Play 20 repetitions. Player 2 must genuinely try to cut off passes and smash lobs.']::text[], ARRAY['Net player close: lob is the right choice — they cannot retreat fast enough.','Net player mid-court: pass is the right choice — they have too much court to cover for the pass.','The lob must go over the net player''s racket with room to spare — aim for 2 feet above reach.','The pass must be low and angled — a high floated pass gives the net player time to volley.','Read the position before the ball is fed — the decision should be made before the ball arrives.']::text[], ARRAY['Same choice every time regardless of net player position — not actually reading the situation.','Lob too short — easily smashed from close to the net.','Pass too high — net player can reach it even from mid-court.']::text[], ARRAY['Mixed position: Player 2 moves to a new position after every 3 repetitions — Player 1 must re-read.','Full point version: play full points with Player 2 at net — real match conditions.','Topspin lob: specifically practice the topspin lob over a close net player.']::text[], ARRAY['matchplay','lob','passing shot','intermediate','decision','net player']::text[], 'json', '{"p1":{"x":200,"y":820},"p2":{"x":200,"y":510},"shots":[{"x1":200,"y1":820,"x2":200,"y2":820},{"x1":200,"y1":815,"x2":200,"y2":100},{"x1":200,"y1":815,"x2":95,"y2":540}],"areas":[{"x":200,"y":100,"r":35},{"x":95,"y":540,"r":25}]}'::jsonb),
  ('MP-027', 'Momentum Shift: Win Three in a Row', 'Matchplay', 'Mental Fitness', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Train the ability to shift momentum by winning consecutive points under pressure. In match play, runs of consecutive points — not individual points — determine the outcome of games and sets. A player who can manufacture a run of 3-4 consecutive points at crucial moments consistently outperforms players who play every point in isolation. This drill specifically trains the consecutive winning mindset.', 'Train the ability to shift momentum by winning consecutive points under pressure. In match play, runs of consecutive points — not individual points — determine the outcome of games and sets. A player who can manufacture a run of 3-4 consecutive points at crucial moments consistently outperforms players who play every point in isolation. This drill specifically trains the consecutive winning mindset.', 'Play points freely. Player 1 must win 3 consecutive points at some stage to win the round. Any time Player 2 wins a point, Player 1''s consecutive count resets to 0. First player to reach 3 consecutive wins the round. Play 5 rounds.', ARRAY['Play competitive points from the serve.','Player 1 must win 3 consecutive points to win the round.','Any point won by Player 2 resets Player 1''s consecutive count to 0.','First to 3 consecutive wins the round. Player 2 is also trying to win 3 consecutive.','Play 5 rounds. Track: how long does it take each player to reach 3 consecutive?']::text[], ARRAY['Each point in a streak builds confidence — allow that confidence to grow, don''t suppress it.','After losing a point and resetting: immediate mental reset, do not dwell on the reset.','To build a streak: play your best patterns, not risky shots. Streaks come from consistency.','Notice what stops streaks: unforced errors or forced errors? The answer points to the fix.','A player who can build 3-point runs against any opponent can win from behind.']::text[], ARRAY['Going for risky shots to quickly win consecutive points — impatience kills streaks.','Mental collapse after a reset — the drill is as much about reset speed as point-winning.','Not tracking consecutive count — must know where you are in the streak.']::text[], ARRAY['5 consecutive: raise the target — harder to achieve, more focus required.','Game streak: both players must win 3 consecutive games — extends the format.','Against the odds: Player 1 starts at -3 (has lost 3 in a row) — must turn it around.']::text[], ARRAY['matchplay','momentum','consecutive','intermediate','mental','streaks']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":200,"y1":70,"x2":110,"y2":820},{"x1":110,"y1":830,"x2":295,"y2":100}],"areas":[{"x":200,"y":850,"r":20},{"x":200,"y":60,"r":20}]}'::jsonb),
  ('MP-028', 'Full Match with Stat Tracking: Complete Performance Review', 'Matchplay', 'Match Assessment', 'matchplay', 'intermediate', 30, 2, 'pairs', 'Play a full 3-set practice match with comprehensive statistics tracking — the most complete match assessment available in practice. Tracking stats during a match reveals the actual game profile: serve percentages, return rates, rally lengths, point-ending shot types, and winner-to-error ratios. Most players have wildly inaccurate self-assessments — the numbers correct this and drive specific, targeted practice.', 'Play a full 3-set practice match with comprehensive statistics tracking — the most complete match assessment available in practice. Tracking stats during a match reveals the actual game profile: serve percentages, return rates, rally lengths, point-ending shot types, and winner-to-error ratios. Most players have wildly inaccurate self-assessments — the numbers correct this and drive specific, targeted practice.', 'Two players play a full 3-set match (or 2 sets + super tiebreak). A third person tracks all statistics, or players record key stats between changeovers. Standard scoring applies throughout.', ARRAY['Play a full 3-set match with normal scoring.','Track: first serve %, second serve %, double faults, aces/service winners, return errors, return winners, winner/FE/UE for each player.','At every changeover, record the game score and any notable patterns.','After the match, calculate each tracked statistic.','Identify the top 2 areas where the match was won or lost — these drive the next week''s training.']::text[], ARRAY['First serve below 55%: serve technique or nerve issue — needs dedicated serve practice.','Return error rate above 30%: return consistency is the priority — return confidence drills needed.','UE:Winner ratio worse than 2:1: tactical conservatism needed — train shot selection.','Win rate below 45% on second serve points: second serve quality is the highest priority issue.','The statistics tell you what to practice — don''t rely on feeling alone.']::text[], ARRAY['Not tracking honestly — all stats must be recorded accurately, including your own errors.','Not acting on the data — the match stats have zero value without targeted follow-up practice.','Tracking too many statistics — focus on 5 key metrics, not 20.']::text[], ARRAY['Video match: film the full match alongside the stats — visual and statistical combined analysis.','Monthly comparison: run this drill monthly, compare stats over time.','Opponent profile: after the match, write a tactical report on the opponent — preparation for future matches.']::text[], ARRAY['matchplay','statistics','assessment','intermediate','full match','data']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":160,"y1":855,"x2":240,"y2":388},{"x1":200,"y1":70,"x2":110,"y2":820},{"x1":200,"y1":60,"x2":295,"y2":820}],"areas":[{"x":200,"y":820,"r":25},{"x":200,"y":100,"r":25}]}'::jsonb),
  ('MP-029', 'Ad Court Pressure: The Game-Deciding Points', 'Matchplay', 'Pressure Scenarios', 'matchplay', 'advanced', 15, 2, 'pairs', 'Train specifically in the ad court — where most games are decided. The ad court sees the highest-pressure points: deuce, ad-in, and ad-out. Most players have asymmetric skill between deuce and ad courts on both serve and return. This drill isolates the ad court to build equal or superior ad court performance under the exact pressure conditions where games are won and lost.', 'Train specifically in the ad court — where most games are decided. The ad court sees the highest-pressure points: deuce, ad-in, and ad-out. Most players have asymmetric skill between deuce and ad courts on both serve and return. This drill isolates the ad court to build equal or superior ad court performance under the exact pressure conditions where games are won and lost.', 'All serves are from the ad court only. All returns are from the ad court position only. Both players play every point as if it is a pressure ad court point — treat each as deuce or ad.', ARRAY['Player 1 serves from the ad court only.','Player 2 returns from the ad court return position only.','Play full points from the ad court start position.','After each point: Player 1 evaluates the serve quality and the tactical execution.','Play 20 ad court points. Track: first serve %, return consistency, and points won.']::text[], ARRAY['Ad court serve options: T to the forehand, wide to the backhand, body serve.','The wide kick serve to the backhand is the most effective ad court serve — train it.','Ad court return: the wide serve pulls the returner off the court. Chip cross-court is the safe response.','Ad court deuce: this is the game-point from behind. Breathe and commit.','Ad court ad-in: this is the game point in your favor. Don''t suddenly become conservative.']::text[], ARRAY['Serving too often to the T from the ad court — the wide serve is underused.','Ad court return being more passive than deuce court — the returner advantage is the same.','Mental tightening in the ad court — happens most with players who have lost games here before.']::text[], ARRAY['Deuce court only version: same drill from the deuce side — compare win rates in both courts.','Ad court tiebreak: play a tiebreak where all serves come from the ad court — extreme focus.','Both courts alternating: serve one from deuce, one from ad — tests the transition in pressure.']::text[], ARRAY['matchplay','ad court','advanced','pressure','game point','decisive']::text[], 'json', '{"p1":{"x":160,"y":860},"p2":{"x":120,"y":60},"shots":[{"x1":160,"y1":850,"x2":80,"y2":388},{"x1":160,"y1":850,"x2":200,"y2":385},{"x1":120,"y1":70,"x2":295,"y2":820},{"x1":295,"y1":830,"x2":100,"y2":100}],"areas":[{"x":80,"y":388,"r":22},{"x":295,"y":820,"r":28}]}'::jsonb),
  ('MP-030', 'Matchplay Grand Finale: The Practice Tournament', 'Matchplay', 'Competitive Play', 'matchplay', 'intermediate', 30, 2, 'pairs', 'Synthesize all matchplay skills in a complete competitive practice tournament format that replicates the full mental and tactical demands of real tournament competition. This drill brings together every element trained in the matchplay category: tactical patterns, pressure point execution, between-point routines, changeover adjustments, serve patterns, return tactics, and mental reset protocols — all in a single competitive context.', 'Synthesize all matchplay skills in a complete competitive practice tournament format that replicates the full mental and tactical demands of real tournament competition. This drill brings together every element trained in the matchplay category: tactical patterns, pressure point execution, between-point routines, changeover adjustments, serve patterns, return tactics, and mental reset protocols — all in a single competitive context.', 'Play a practice tournament match: 2 sets with a 10-point super tiebreak if needed. Both players bring their complete tactical toolkit — serve patterns, return positioning, emotional reset routine, and changeover review. This is a genuine competition, not a practice drill.', ARRAY['Announce the format: best of 2 sets + 10-point tiebreak if 1-1.','Both players use their full between-point routines and changeover reviews.','Both players track their own: first serve %, double faults, and win rate on ad court points.','At every changeover, complete the 3-question tactical review (what works, what doesn''t, one change).','After the match: both players provide one piece of specific tactical feedback to each other.']::text[], ARRAY['This is the integration test — every skill trained in every category should be present.','Between-point routine: non-negotiable. Complete it after every point.','Changeover review: answer all 3 questions at every changeover, even if winning.','Tactical feedback after the match should be specific: not ''play better'' but ''use more kick serve on deuce court''.','The practice tournament is only valuable if played at full competitive intensity — there are no practice points.']::text[], ARRAY['Abandoning routines under competitive pressure — this is exactly when they are most needed.','Not doing the changeover review when winning — momentum can shift, adjustment is always relevant.','Not providing honest feedback after the match — growth requires honest communication.']::text[], ARRAY['Round robin tournament: 3-4 players, each plays everyone — more variety and more competition.','Recorded tournament: film the full match and review afterward — video analysis combined.','Monthly tournament: compete monthly with the same opponents, track win/loss records and stat improvement.']::text[], ARRAY['matchplay','tournament','competitive','intermediate','comprehensive','integration']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":200,"y1":70,"x2":280,"y2":820},{"x1":280,"y1":830,"x2":95,"y2":100},{"x1":160,"y1":855,"x2":240,"y2":388},{"x1":200,"y1":60,"x2":110,"y2":820}],"areas":[{"x":280,"y":820,"r":28},{"x":95,"y":100,"r":28},{"x":110,"y":820,"r":28}]}'::jsonb),
  ('RT-001', 'Return Ready Position and Split Step', 'Return', 'Technique', 'return', 'beginner', 10, 2, 'pairs', 'Build the correct return ready position and split step timing — the two most fundamental return skills. Most return errors begin before the ball even arrives: either the player is standing in the wrong position, or their split step timing is off. This drill isolates and trains exactly those two components before any swing mechanics are introduced.', 'Build the correct return ready position and split step timing — the two most fundamental return skills. Most return errors begin before the ball even arrives: either the player is standing in the wrong position, or their split step timing is off. This drill isolates and trains exactly those two components before any swing mechanics are introduced.', 'Player 1 stands in the return position on the deuce side. Player 2 serves from the opposite baseline. Player 1 focuses only on the ready position and split step — no emphasis yet on where the return goes.', ARRAY['Player 1 stands in the ready position: weight on the balls of the feet, knees slightly bent, racket centered in front, eyes on the server.','Player 2 serves from the deuce court at medium pace.','Player 1 split steps as Player 2''s racket contacts the ball — and immediately identifies the direction.','Player 1 returns the ball anywhere in the court — quality of return is not the focus.','After 15 returns from the deuce side, switch to the ad side. Repeat 3 rounds.']::text[], ARRAY['Stand 1-2 feet behind the baseline for a medium-pace server — closer for slow servers, further for fast servers.','Weight forward on the balls of the feet — heels never touch the ground in the ready position.','Split step exactly as the server''s racket contacts the ball — use the contact sound as the trigger.','After the split step, first step must go toward the ball — decisive, not tentative.','Keep your eyes on the server''s shoulder and toss — these are the earliest cues to serve direction.']::text[], ARRAY['Standing flat-footed — cannot react quickly from a flat-footed position.','Split stepping too early (before contact) — still in the air when the ball arrives.','Split stepping too late (after the ball has passed) — no time to move.']::text[], ARRAY['Eyes closed drill: Player 1 closes eyes during the toss, opens on the serve — trains sound-based read.','Footwork only: Player 1 moves into position but doesn''t swing — pure footwork training.','Vary the serve pace: Player 2 alternates slow and fast — Player 1 must adjust split step timing.']::text[], ARRAY['return','ready position','split step','beginner','technique','foundation']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":200,"y2":385},{"x1":280,"y1":70,"x2":240,"y2":820}],"areas":[{"x":240,"y":820,"r":30}]}'::jsonb),
  ('RT-002', 'Block Return: Absorbing Pace on Fast Serves', 'Return', 'Technique', 'return', 'beginner', 10, 2, 'pairs', 'Develop the block return — the compact, abbreviated stroke used to handle fast serves when there is no time for a full swing. The block return is the foundation of returning hard serves. Rather than trying to generate pace of your own, the block uses the server''s pace and redirects it with a firm, compact motion. This is the primary return used at the highest levels of the game against first serves.', 'Develop the block return — the compact, abbreviated stroke used to handle fast serves when there is no time for a full swing. The block return is the foundation of returning hard serves. Rather than trying to generate pace of your own, the block uses the server''s pace and redirects it with a firm, compact motion. This is the primary return used at the highest levels of the game against first serves.', 'Player 2 serves from the deuce and ad courts at increasing pace. Player 1 must return every serve with a block return — no full swing allowed. The goal is simply to get the ball back consistently and deep.', ARRAY['Player 2 serves from the deuce court at 60% pace initially.','Player 1 returns with a block return — racket starts up, compact punch forward, no backswing.','After 10 returns, Player 2 increases to 80% pace.','After 10 more, Player 2 serves at full pace.','Switch to the ad court and repeat. Track in-percentage at each pace level.']::text[], ARRAY['Racket starts up in the ready position — there is no time to take it back.','Meet the ball in front of the body — if it gets beside you, the block goes in a random direction.','Firm wrist and arm — the block is a wall that redirects pace, not a soft jab.','Open the racket face slightly — helps the ball clear the net even on compact swings.','Aim for depth, not for a winner — a deep block return is highly effective.']::text[], ARRAY['Trying to take a full swing on a fast serve — contact happens before the swing is ready.','Loose wrist — sends the return in an unpredictable direction.','Letting the ball get too close to the body — causes a cramped, jammed return.']::text[], ARRAY['Block to specific targets: cross-court only, or down-the-line only.','Block and advance: Player 1 block returns and immediately advances to the net.','Reaction block: Player 2 serves wide without warning — Player 1 must block from a stretched position.']::text[], ARRAY['return','block return','beginner','technique','fast serve','compact']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":70,"x2":100,"y2":820}],"areas":[{"x":100,"y":820,"r":30}]}'::jsonb),
  ('RT-003', 'Return Cross-Court: The Safest Target', 'Return', 'Placement', 'return', 'beginner', 10, 2, 'pairs', 'Train the cross-court return as the primary, default return target. The cross-court return is the highest-percentage return in tennis for three reasons: it travels over the lowest part of the net, it is the most natural directional extension of the return swing, and it pushes the server wide rather than opening the court. This drill builds cross-court return as the automatic default before introducing other directions.', 'Train the cross-court return as the primary, default return target. The cross-court return is the highest-percentage return in tennis for three reasons: it travels over the lowest part of the net, it is the most natural directional extension of the return swing, and it pushes the server wide rather than opening the court. This drill builds cross-court return as the automatic default before introducing other directions.', 'Player 2 serves from both courts. Player 1 must return every serve cross-court — no exceptions. Cones mark the target zone in each cross-court corner.', ARRAY['Player 2 serves from the deuce court. Player 1 returns cross-court to the ad side.','After 10 returns, Player 2 serves from the ad court. Player 1 returns cross-court to the deuce side.','Every return must land cross-court — any down-the-line return does not count.','Target zone: the deep cross-court corner, past the service line.','Play 4 rounds of 10 serves from each court.']::text[], ARRAY['Cross-court return from deuce court: swing the racket face toward the left side of the court.','Cross-court return from ad court: swing the racket face toward the right side of the court.','The cross-court return uses the most natural follow-through — don''t fight the instinct.','Aim 3 feet over the net — the cross-court net is at its lowest point.','A deep cross-court return immediately puts the server in a neutral or defensive position.']::text[], ARRAY['Returning down-the-line instinctively — requires a conscious correction to go cross-court.','Returning short and mid-court — gives the server an easy attack.','Aiming at the line instead of 3 feet inside it — causes unnecessary wide errors.']::text[], ARRAY['Score only deep cross-court returns: landing past the service line = 1 point, past the 3-foot cone = 2 points.','Cross-court placement challenge: 8 out of 10 in the target zone.','Follow the return: after the cross-court return, Player 1 advances to the net — baseline to net on the return.']::text[], ARRAY['return','cross-court','placement','beginner','safety','default target']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":70,"x2":120,"y2":820}],"areas":[{"x":120,"y":820,"r":30}]}'::jsonb),
  ('RT-004', 'Return Down the Line: The High-Risk Weapon', 'Return', 'Placement', 'return', 'intermediate', 10, 2, 'pairs', 'Develop the down-the-line return — the highest-risk, highest-reward return option. The DTL return is used to: surprise a server who is cheating to cover the cross-court, punish a wide serve by going back behind the server, or create a pattern change. This drill trains both the technical execution (redirecting the ball DTL) and the tactical judgment of when to use it.', 'Develop the down-the-line return — the highest-risk, highest-reward return option. The DTL return is used to: surprise a server who is cheating to cover the cross-court, punish a wide serve by going back behind the server, or create a pattern change. This drill trains both the technical execution (redirecting the ball DTL) and the tactical judgment of when to use it.', 'Player 2 serves from the deuce court. Player 1 must return every ball down-the-line — to the deuce side on Player 2''s court. Cones mark the target zone deep in the DTL corner.', ARRAY['Player 2 serves from the deuce court at medium pace.','Player 1 must return every serve down-the-line — to the deuce side, away from the cross-court.','After 10 deuce-court DTL returns, switch to ad court: Player 1 returns DTL to the ad side.','Track accuracy: how many land in the target zone? Target: 6 out of 10.','After 2 sets of DTL practice, mix CC and DTL freely — Player 2 guesses which is coming.']::text[], ARRAY['DTL from deuce court: take the ball slightly earlier (more in front) than cross-court.','DTL from ad court: let the ball travel slightly further (more beside the body) than cross-court.','The same serve can go two directions — the difference is contact point, not swing path.','DTL is higher risk: the net is higher and the court is shorter. Add pace to compensate.','Use the DTL when the server is clearly leaning toward the cross-court return.']::text[], ARRAY['Going DTL on a wide serve — the angle makes DTL extremely difficult from a wide position.','DTL return landing short — gives the server an easy attack.','Using DTL too frequently — it must remain a surprise weapon, not a default.']::text[], ARRAY['DTL then CC alternation: Player 1 alternates return directions — Player 2 must guess.','Wide serve DTL challenge: Player 2 serves wide — Player 1 attempts the difficult DTL from wide.','Return rally: after the DTL return, play out the full point — test the consequences.']::text[], ARRAY['return','down-the-line','placement','intermediate','weapon','risk']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":70,"x2":295,"y2":820}],"areas":[{"x":295,"y":820,"r":28}],"cones":[{"x":295,"y":820}]}'::jsonb),
  ('RT-005', 'Chip Return: Low and Through the Court', 'Return', 'Technique', 'return', 'intermediate', 10, 2, 'pairs', 'Develop the chip return — a slice backhand return that stays low and skids through the court. The chip return is used primarily on second serves and wide serves where a full drive return is too difficult. Unlike a drive return, the chip uses the server''s pace and stays low — forcing the server to hit up on the next ball. It is the classic chip-and-charge trigger: chip the return and follow it to the net.', 'Develop the chip return — a slice backhand return that stays low and skids through the court. The chip return is used primarily on second serves and wide serves where a full drive return is too difficult. Unlike a drive return, the chip uses the server''s pace and stays low — forcing the server to hit up on the next ball. It is the classic chip-and-charge trigger: chip the return and follow it to the net.', 'Player 2 serves from both courts at moderate pace — simulating a second serve. Player 1 must return with a chip — a sliced, low, compact backhand return. The chip should barely clear the net and skid through the court.', ARRAY['Player 2 serves at moderate second-serve pace from the deuce court.','Player 1 uses a chip return — a compact slice backhand motion.','The chip must stay low: target clearing the net by less than 1 foot.','After 10 chip returns from the deuce court, switch to the ad court.','After mastering the static chip, Player 1 follows the chip to the net on every return.']::text[], ARRAY['Short backswing — the chip is compact by design, not a full slice swing.','High to low racket path — slight downward motion through contact creates the low trajectory.','Open racket face just enough to clear the net — too open creates a floater.','Aim for the T (center service line) or DTL — these angles minimize the return angle available.','Stay sideways through contact — opening up creates a high floated chip.']::text[], ARRAY['Chip floating too high — gives the server an easy attack ball.','Chip landing too short — sits up in the service box, ideal for the server to attack.','No follow-through — stopping the racket before completion kills direction control.']::text[], ARRAY['Chip and charge: return is always followed by a sprint to the net.','Chip placement: alternate between T chip and wide chip — keep the server guessing.','Chip under pressure: Player 2 serves at full first-serve pace — Player 1 must still chip.']::text[], ARRAY['return','chip','slice','intermediate','backhand','second serve']::text[], 'json', '{"p1":{"x":120,"y":60},"p2":{"x":160,"y":860},"shots":[{"x1":160,"y1":850,"x2":250,"y2":388},{"x1":120,"y1":70,"x2":200,"y2":810}],"areas":[{"x":200,"y":810,"r":30}]}'::jsonb),
  ('RT-006', 'Drive Return: Attacking the Second Serve', 'Return', 'Technique', 'return', 'intermediate', 12, 2, 'pairs', 'Develop the drive return — a full, aggressive groundstroke taken on a second serve. The drive return is the primary weapon against weak second serves. When the server offers a slow, spinny, or misdirected second serve, the returner must step in, take the ball early, and drive it with full conviction. The drive return immediately puts the server on the defensive and changes the balance of the point.', 'Develop the drive return — a full, aggressive groundstroke taken on a second serve. The drive return is the primary weapon against weak second serves. When the server offers a slow, spinny, or misdirected second serve, the returner must step in, take the ball early, and drive it with full conviction. The drive return immediately puts the server on the defensive and changes the balance of the point.', 'Player 2 serves second serves only — kick or slice at moderate pace. Player 1 must step inside the baseline, take the ball early, and drive a full groundstroke return. No chip returns allowed during this drill.', ARRAY['Player 2 serves second serves from the deuce court at 60-70% pace.','Player 1 steps inside the baseline to receive — foot should be inside the baseline.','Player 1 drives the return with a full forehand or backhand groundstroke.','Target: cross-court deep corner, past the service line.','Repeat 15 drive returns from each court. Track: how many land in the target zone?']::text[], ARRAY['Step inside the baseline — if you stay on the baseline, the second serve pulls you back.','Take the ball early — before it reaches the peak of its bounce if possible.','Full backswing and follow-through — this is a groundstroke, not a block.','Drive through the ball with full hip and shoulder rotation.','The drive return should feel like a forehand or backhand from mid-court — same motion.']::text[], ARRAY['Staying on the baseline for a second serve — giving up the attack position.','Blocking instead of driving — uses only a fraction of the available power.','Stepping in but not completing the swing — foot in, but arm stays short.']::text[], ARRAY['Drive return plus one: after the drive return, Player 2 feeds a ball — Player 1 attacks again.','Inside-in drive: step inside and go inside-in forehand — attack the open court.','Drive return to DTL: step in and go down-the-line — maximum aggression.']::text[], ARRAY['return','drive','aggressive','intermediate','second serve','attack']::text[], 'json', '{"p1":{"x":280,"y":90},"p2":{"x":240,"y":860},"moves":[{"x1":280,"y1":60,"x2":280,"y2":90}],"shots":[{"x1":240,"y1":850,"x2":220,"y2":388},{"x1":280,"y1":90,"x2":100,"y2":820}],"areas":[{"x":100,"y":820,"r":30}]}'::jsonb),
  ('RT-007', 'Return from Wide Serve: Deuce Court', 'Return', 'Placement', 'return', 'intermediate', 12, 2, 'pairs', 'Train the return of a wide serve from the deuce court — one of the most difficult return situations. The wide serve pulls the returner off the court, reduces the available return angles, and requires excellent footwork to reach in time. This drill trains both the movement to the wide serve and the limited return options available from a stretched position.', 'Train the return of a wide serve from the deuce court — one of the most difficult return situations. The wide serve pulls the returner off the court, reduces the available return angles, and requires excellent footwork to reach in time. This drill trains both the movement to the wide serve and the limited return options available from a stretched position.', 'Player 2 serves wide slice serves to the deuce court — pulling Player 1 outside the singles sideline. Player 1 must reach the wide serve and return it back into the court. The cross-court return is almost always the only viable option from a wide position.', ARRAY['Player 2 serves wide slice serves from the deuce court repeatedly.','Player 1 sprints wide to reach the serve and returns cross-court.','Target: return landing inside the ad service box or ad baseline corner.','Track: what percentage of wide serves can Player 1 return successfully? Target: 70%.','After 15 wide serve returns, Player 2 mixes wide and T — Player 1 must read and react.']::text[], ARRAY['First step: move laterally toward the ball immediately after the split step.','From a wide position, cross-court is almost always the only viable direction.','Use a compact swing from the wide position — there is less time and less balance available.','Open stance wide return: plant your outside foot and rotate from there.','After the return, sprint back toward the center — don''t stop wide.']::text[], ARRAY['Trying to go DTL from a wide position — extremely high risk, usually goes wide.','No recovery after the wide return — stays wide and gives up the center.','Late split step — cannot get to the wide ball in time.']::text[], ARRAY['Wide return plus recovery: Player 2 hits a second ball to the center after Player 1''s return.','No-man''s land return: Player 2 serves a wide kick — Player 1 must handle the high bounce from wide.','Wide return accuracy: how many wide returns land inside the cross-court service box?']::text[], ARRAY['return','wide serve','deuce court','intermediate','movement','positioning']::text[], 'json', '{"p1":{"x":340,"y":60},"p2":{"x":240,"y":860},"moves":[{"x1":280,"y1":60,"x2":340,"y2":60}],"shots":[{"x1":240,"y1":850,"x2":330,"y2":388},{"x1":340,"y1":65,"x2":110,"y2":820}],"areas":[{"x":110,"y":820,"r":30}]}'::jsonb),
  ('RT-008', 'Return from T Serve: Reading the Middle', 'Return', 'Reading', 'return', 'beginner', 10, 2, 'pairs', 'Train the return of a T serve — a serve aimed at the center service line. The T serve eliminates most return angles and forces the returner to handle the ball directly in front or slightly to the backhand side. This drill trains both the positioning for T serves and the limited but effective return options available from this central position.', 'Train the return of a T serve — a serve aimed at the center service line. The T serve eliminates most return angles and forces the returner to handle the ball directly in front or slightly to the backhand side. This drill trains both the positioning for T serves and the limited but effective return options available from this central position.', 'Player 2 serves T serves consistently from the deuce court. Player 1 positions slightly closer to center than usual to cover the T. Player 1 returns cross-court or DTL depending on the serve quality.', ARRAY['Player 2 serves T serves from the deuce court.','Player 1 adjusts position: 2 feet closer to center than standard deuce court position.','Player 1 returns — cross-court is the primary target, DTL is the secondary option.','After 10 T serve returns from the deuce court, switch to the ad court.','Track: what percentage of T serves does Player 1 return successfully? Target: 75%.']::text[], ARRAY['Stand closer to center for the T serve — if you stand wide, the T serve jams you.','The T serve often comes at the body or slightly to the backhand side from deuce court.','Use a two-handed backhand block or a forehand block from this central position.','Cross-court is the natural direction from the T return position — don''t fight it.','The T serve forces a reply down the middle — the server already has the center covered, so go wide.']::text[], ARRAY['Standing too wide — T serve jams the body and the return goes back to the center.','Slow first step to the T serve — the ball arrives quickly from the center.','Trying to go DTL from the T return — very difficult and usually goes wide.']::text[], ARRAY['T vs wide reading: Player 2 mixes T and wide — Player 1 must read and position correctly.','T return to DTL: specifically practice the difficult DTL return off a T serve.','T serve and rally: after the T return, play out the full point — server starts with the advantage.']::text[], ARRAY['return','T serve','positioning','beginner','reading','central']::text[], 'json', '{"p1":{"x":230,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":200,"y2":380},{"x1":230,"y1":65,"x2":100,"y2":820}],"areas":[{"x":100,"y":820,"r":30}]}'::jsonb),
  ('RT-009', 'Return and Rally: Neutralizing from the Return', 'Return', 'Tactical', 'return', 'intermediate', 15, 2, 'pairs', 'Train the return as a rally-starting shot rather than a point-ending shot. Many players try to hit winners on the return — a high-risk strategy that leads to unnecessary errors. This drill trains the neutralizing return: getting the ball in deep and cross-court, then winning the point in the rally. The return is a setup shot; the rally is where the point is won.', 'Train the return as a rally-starting shot rather than a point-ending shot. Many players try to hit winners on the return — a high-risk strategy that leads to unnecessary errors. This drill trains the neutralizing return: getting the ball in deep and cross-court, then winning the point in the rally. The return is a setup shot; the rally is where the point is won.', 'Player 2 serves from both courts. Player 1 returns cross-court deep and plays out the full point. The rule: Player 1 must return the ball first, and the point is scored normally after the return.', ARRAY['Player 2 serves from the deuce court. Player 1 returns cross-court.','Both players play out the full point after the return.','Player 1''s goal: neutral deep return, then win the rally — not a winner on the return.','After 10 points from deuce, switch to ad. Play 3 rounds of 10 points per court.','Track: what percentage of points does Player 1 win after a successful return?']::text[], ARRAY['The return is a rally starter — treat it like the first ball of a rally, not a return winner.','Deep and cross-court is the safest and most effective neutralizing return.','After the return, immediately prepare for the server''s reply — don''t watch the return.','The server has the initiative — the returner''s job is to take it away over the course of the rally.','A return that stays in starts a rally; a return winner attempt that misses gives the server a free point.']::text[], ARRAY['Going for return winners — high-risk, low-reward against good servers.','Return landing short — gives the server an easy attack on the next ball.','Not preparing for the rally after the return — caught thinking instead of moving.']::text[], ARRAY['Return and attack: on second serves, Player 1 may drive the return aggressively.','Return and come in: Player 1 returns and follows the return to the net.','Score tracking: play full sets — track first serve return won % and second serve return won %.']::text[], ARRAY['return','rally','neutral','intermediate','tactical','consistency']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":70,"x2":110,"y2":820},{"x1":110,"y1":830,"x2":290,"y2":100}],"areas":[{"x":110,"y":820,"r":28}]}'::jsonb),
  ('RT-010', 'Reading the Toss: Predicting Serve Direction', 'Return', 'Reading', 'return', 'advanced', 12, 2, 'pairs', 'Train the ability to predict serve direction from the ball toss — the earliest possible cue available to the returner. The toss position is the server''s biggest tell: a toss further right usually means wide from the deuce court, a toss further inside usually means T. Reading the toss allows the returner to start moving before the ball is even hit, gaining a critical head start on every return.', 'Train the ability to predict serve direction from the ball toss — the earliest possible cue available to the returner. The toss position is the server''s biggest tell: a toss further right usually means wide from the deuce court, a toss further inside usually means T. Reading the toss allows the returner to start moving before the ball is even hit, gaining a critical head start on every return.', 'Player 2 serves from the deuce court to various locations. Player 1 must call the serve direction — ''T'', ''wide'', or ''body'' — before the ball is hit, based only on the toss position. Player 2 confirms after each serve.', ARRAY['Player 2 serves from the deuce court to random locations without declaring.','Player 1 must call the direction before the serve is hit — based on the toss.','Player 2 confirms the intended location after each serve.','Track: how often does Player 1 correctly read the toss? Target: 60%+ correct.','After 20 deuce court serves, switch to ad court. Repeat.']::text[], ARRAY['Watch the toss arm: if it goes further right (for right-hander serving deuce), usually wide.','Toss inside (left) from deuce court usually means T or body serve.','Watch the server''s shoulder turn: if they turn more, usually more spin (kick or slice).','You don''t need to be right 100% of the time — even 60% correct reading gives a massive advantage.','Even if you read wrong, the split step still gives you time to adjust.']::text[], ARRAY['Watching the ball after the toss instead of the server''s body — loses the pre-contact cues.','Moving too early based on the read — must wait for the split step before committing.','Giving up on reading after a few wrong guesses — the reading skill takes time to develop.']::text[], ARRAY['Toss-only test: Player 2 tosses but doesn''t serve — Player 1 calls the direction purely from the toss.','Reading competition: track Player 1''s reading accuracy across 50 serves — measure improvement.','Reading with movement: Player 1 reads the toss and starts moving early — track how much earlier they arrive.']::text[], ARRAY['return','reading','toss','advanced','anticipation','serve prediction']::text[], 'json', '{"p1":{"x":280,"y":60},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":200,"y2":378},{"x1":240,"y1":850,"x2":318,"y2":388},{"x1":240,"y1":850,"x2":152,"y2":382}],"cones":[{"x":200,"y":378},{"x":318,"y":388},{"x":152,"y":382}]}'::jsonb),
  ('RT-011', 'Return Positioning by Server Type', 'Return', 'Tactical', 'return', 'intermediate', 12, 2, 'pairs', 'Train the ability to adjust return position based on the server''s tendencies and serve type. Returner positioning is one of the most tactically sophisticated aspects of the return game. Standing in the wrong spot gives the server an automatic advantage on every serve. This drill develops the habit of actively adjusting position based on what the server shows.', 'Train the ability to adjust return position based on the server''s tendencies and serve type. Returner positioning is one of the most tactically sophisticated aspects of the return game. Standing in the wrong spot gives the server an automatic advantage on every serve. This drill develops the habit of actively adjusting position based on what the server shows.', 'Player 2 serves as three different ''types'': hard flat server, kick serve specialist, and wide slice specialist. For each type, Player 1 must adjust their starting position. Player 2 announces which type they are serving as before each set.', ARRAY['Round 1: Player 2 serves as a ''hard flat server''. Player 1 positions 2 feet further back.','Round 2: Player 2 serves as a ''kick specialist''. Player 1 positions further back and slightly wide — the kick bounces high.','Round 3: Player 2 serves as a ''wide slice specialist''. Player 1 positions slightly wider to cover the wide serve.','After each round, discuss: did the positioning help? What would you change?','Play 10 points per round. Track: return success rate at each position.']::text[], ARRAY['Hard flat server: stand further back — the extra foot of distance gives more reaction time.','Kick specialist: stand further back AND be ready to move wide — the kick pushes you out.','Wide slice specialist: cheat slightly wide on the side being served — cover the angle.','Never give up the center completely — a slight adjustment, not a full repositioning.','Adjust your position during the warm-up based on what the server shows you.']::text[], ARRAY['Standing in the same position regardless of server type — one position does not fit all servers.','Over-adjusting: cheating too far to one side gives up the other completely.','Not noticing the server''s patterns during warm-up — crucial information is ignored.']::text[], ARRAY['Identify the type: Player 2 serves without announcing type — Player 1 identifies and adjusts mid-match.','Mixed types: Player 2 switches types after every 3 serves — Player 1 must spot and readjust.','Match simulation: play a practice set with Player 1 consciously adjusting return position every game.']::text[], ARRAY['return','positioning','tactical','intermediate','server type','adjustment']::text[], 'json', '{"p1":{"x":280,"y":80},"p2":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":310,"y2":385},{"x1":280,"y1":80,"x2":110,"y2":830}],"areas":[{"x":240,"y":80,"r":35},{"x":110,"y":830,"r":28}]}'::jsonb),
  ('RT-012', 'Return of Kick Serve: Handling the High Bounce', 'Return', 'Technique', 'return', 'intermediate', 12, 2, 'pairs', 'Train the specific challenge of returning a kick serve that bounces above shoulder height. The kick serve is the most effective second serve at competitive levels because it forces the returner to hit from an uncomfortable high contact point. Most players either back up to let it drop (losing attack position) or hit from too high (weak return). This drill trains the optimal response: step back slightly, take the ball at chest height on the rise, and drive it cross-court.', 'Train the specific challenge of returning a kick serve that bounces above shoulder height. The kick serve is the most effective second serve at competitive levels because it forces the returner to hit from an uncomfortable high contact point. Most players either back up to let it drop (losing attack position) or hit from too high (weak return). This drill trains the optimal response: step back slightly, take the ball at chest height on the rise, and drive it cross-court.', 'Player 2 serves kick serves from both courts designed to bounce above shoulder height. Player 1 must handle every kick serve with a quality return. Player 1 may step back slightly to take the ball at chest height on the rise.', ARRAY['Player 2 serves high-kicking serves from the deuce court to Player 1''s backhand.','Player 1 steps back one step to take the ball as it rises — at chest height, not shoulder height.','Player 1 returns cross-court with a drive or chip — whatever is most natural.','After 10 returns from deuce, switch to ad court.','Track: return quality on a scale of 1-3 (1=in court, 2=deep, 3=deep and cross-court target).']::text[], ARRAY['Take one small step back to take the ball on the rise at chest height — not at shoulder or above.','Swing path must be low-to-high to handle the kick — meet the ball and brush upward.','Cross-court is the safest return off the kick — the natural swing path goes that direction.','Against a kick to the backhand: take it slightly later and drive through the ball.','Do NOT let the kick bounce twice — the returner who waits for the ball to drop concedes the point.']::text[], ARRAY['Staying in the same position and taking the kick at shoulder height — too uncomfortable.','Retreating too far back — gives the server the attack and concedes baseline position.','Blocking the kick instead of driving — produces a weak, short return.']::text[], ARRAY['Kick to the forehand: Player 2 kick serves to Player 1''s forehand — unusual but effective.','Kick return attack: Player 1 must drive the kick return aggressively — no chips allowed.','Kick serve and rally: play full points after the kick — track server''s advantage on kick serves.']::text[], ARRAY['return','kick serve','high bounce','intermediate','backhand','technique']::text[], 'json', '{"p1":{"x":120,"y":85},"p2":{"x":160,"y":860},"moves":[{"x1":120,"y1":60,"x2":120,"y2":85}],"shots":[{"x1":160,"y1":850,"x2":250,"y2":388},{"x1":120,"y1":85,"x2":295,"y2":830}],"areas":[{"x":295,"y":830,"r":30}]}'::jsonb),
  ('RT-013', 'Return and Chip and Charge', 'Return', 'Tactical', 'return', 'intermediate', 12, 2, 'pairs', 'Develop the chip return and charge pattern — one of the most aggressive and effective return tactics available. On a second serve, the returner chips a low, skidding return and immediately sprints to the net. This pattern eliminates the server''s rally advantage, creates an immediate net position, and forces the server to hit a passing shot from behind the baseline while still recovering from their serve.', 'Develop the chip return and charge pattern — one of the most aggressive and effective return tactics available. On a second serve, the returner chips a low, skidding return and immediately sprints to the net. This pattern eliminates the server''s rally advantage, creates an immediate net position, and forces the server to hit a passing shot from behind the baseline while still recovering from their serve.', 'Player 2 serves second serves from both courts. Player 1 chips a return and immediately sprints to the net on every ball. Player 2 attempts a passing shot — Player 1 volleys the finish.', ARRAY['Player 2 serves a second serve from the deuce court.','Player 1 chips a compact slice return — low and deep, aimed at the T or DTL.','Player 1 immediately sprints to the net — no hesitation after the chip.','Player 2 attempts a passing shot from behind the baseline.','Player 1 split steps and volleys the finish. Play each as a full point. Repeat 15 times per court.']::text[], ARRAY['The chip must be low and deep — a high chip gives the server an easy passing shot angle.','Commit to the net charge the moment the chip leaves the racket — no hesitation.','Sprint diagonally toward the net — aim for the T to cut off both passing angles.','Split step as Player 2 contacts the passing shot — always, even mid-sprint.','Volley to the open court — the server is still recovering from their serve motion.']::text[], ARRAY['Chip landing short and floating — gives the server an easy attack from the service box.','Hesitating after the chip — arrives at the net too late for the volley.','No split step before the volley — cannot react to the passing shot direction.']::text[], ARRAY['Chip and charge on first serves: Player 1 chips and charges even on first serves.','Chip angle and charge: the chip goes sharply wide to open the court, then Player 1 charges.','Doubles chip and charge: works especially well when the partner is already at the net.']::text[], ARRAY['return','chip','charge','net play','intermediate','aggressive','tactical']::text[], 'json', '{"p1":{"x":280,"y":550},"p2":{"x":240,"y":860},"moves":[{"x1":280,"y1":60,"x2":280,"y2":120},{"x1":280,"y1":120,"x2":280,"y2":550}],"shots":[{"x1":240,"y1":850,"x2":310,"y2":388},{"x1":280,"y1":115,"x2":200,"y2":820},{"x1":240,"y1":870,"x2":240,"y2":620},{"x1":278,"y1":545,"x2":100,"y2":120}],"areas":[{"x":100,"y":120,"r":25}]}'::jsonb),
  ('RT-014', 'Second Serve Return Attack: Step In and Drive', 'Return', 'Technique', 'return', 'intermediate', 12, 2, 'pairs', 'Train the aggressive second serve return — one of the highest-value skills in competitive tennis. A player who consistently attacks second serves puts enormous pressure on the server, forces double faults under pressure, and wins a disproportionate number of return games. This drill specifically trains stepping inside the baseline and driving the return with full aggression on every second serve.', 'Train the aggressive second serve return — one of the highest-value skills in competitive tennis. A player who consistently attacks second serves puts enormous pressure on the server, forces double faults under pressure, and wins a disproportionate number of return games. This drill specifically trains stepping inside the baseline and driving the return with full aggression on every second serve.', 'Player 2 serves only second serves from both courts. Player 1 must step inside the baseline before the ball bounces and attack the return aggressively. Conservative or neutral returns do not count — the goal is a return that puts the server immediately on the defensive.', ARRAY['Player 2 serves second serves from the deuce court.','Player 1 steps 1-2 feet inside the baseline before the serve bounces.','Player 1 drives the return with full aggression — forehand or backhand groundstroke.','Target: return that lands deep and forces a defensive reply from the server.','Play 15 aggressive returns from each court. Track: how many put the server immediately on defense?']::text[], ARRAY['Step inside the baseline before the ball bounces — position is the key to second serve attacks.','Take the ball early — stepping in and taking it on the rise increases pressure dramatically.','Commit fully to the swing — hesitation produces a halfhearted return that sits up.','Aim cross-court deep — the most reliable aggressive return direction.','After the aggressive return, be ready to rally — the server will try to hit a counterpunch.']::text[], ARRAY['Stepping in but still chipping — defeats the purpose of the inside position.','Stepping in too early — the ball bounces past you.','Aggressive swing but late contact — produces an error rather than an attack.']::text[], ARRAY['Inside-out attack: step in and go inside-out forehand — most aggressive option.','Pressure set: Player 1 must attack every second serve for an entire practice set.','Track the data: over 30 second serves, what percentage of attacks put the server on defense?']::text[], ARRAY['return','second serve','attack','aggressive','intermediate','step-in']::text[], 'json', '{"p1":{"x":280,"y":90},"p2":{"x":240,"y":860},"moves":[{"x1":280,"y1":60,"x2":280,"y2":90}],"shots":[{"x1":240,"y1":850,"x2":220,"y2":385},{"x1":280,"y1":90,"x2":100,"y2":830}],"areas":[{"x":100,"y":830,"r":28}],"cones":[{"x":100,"y":830}]}'::jsonb),
  ('RT-015', 'Return of Body Serve: Getting Out of the Way', 'Return', 'Technique', 'return', 'intermediate', 10, 2, 'pairs', 'Train the response to body serves — serves aimed directly at the returner''s hip or shoulder. The body serve is one of the most effective serves at all levels because it jams the returner, removes their swing space, and forces a cramped, weak return. The solution requires a quick lateral step to create space before swinging — a movement that must become automatic.', 'Train the response to body serves — serves aimed directly at the returner''s hip or shoulder. The body serve is one of the most effective serves at all levels because it jams the returner, removes their swing space, and forces a cramped, weak return. The solution requires a quick lateral step to create space before swinging — a movement that must become automatic.', 'Player 2 serves body serves from both courts — aimed directly at Player 1''s dominant hip or shoulder. Player 1 must step sideways to create space and return the ball.', ARRAY['Player 2 serves body serves from the deuce court — aimed at Player 1''s dominant side.','Player 1 must step sideways immediately to create space before swinging.','After creating space, Player 1 drives a return cross-court.','After 10 body serve returns from deuce, switch to ad court.','Track: how many body serves does Player 1 successfully create space and return?']::text[], ARRAY['Step sideways immediately — one quick step creates enough space for the swing.','Step away from the ball, not toward it — resist the instinct to reach for body serves.','After the step, swing normally — the step was the adjustment, the swing should be unchanged.','Cross-court is the easiest direction after a body serve — the step opens that angle.','Train the body serve response until the step becomes automatic — it must be instinctive.']::text[], ARRAY['No lateral step — tries to swing from a jammed position, produces a weak return.','Stepping toward the ball instead of away — makes the jam worse.','Too large a step — takes too long and the ball is already past.']::text[], ARRAY['Mixed body and wide: Player 2 alternates body and wide serves — Player 1 must read and react.','Forehand body serve: Player 2 jams the forehand — Player 1 must step to the right.','Body serve pressure: Player 2 serves body serves at full pace — increases the jam effect.']::text[], ARRAY['return','body serve','footwork','intermediate','technique','space creation']::text[], 'json', '{"p1":{"x":245,"y":60},"p2":{"x":240,"y":860},"moves":[{"x1":280,"y1":60,"x2":245,"y2":60}],"shots":[{"x1":240,"y1":850,"x2":155,"y2":382},{"x1":245,"y1":65,"x2":100,"y2":820}],"areas":[{"x":100,"y":820,"r":28}]}'::jsonb)
